<?php
require __DIR__.'/config.php';$admin=require_role('admin');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
if($action==='save_car'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$type=$_POST['type']??'';$seats=(int)($_POST['seats']??5);$price=(float)($_POST['price']??0);$image=trim($_POST['image_url']??'');$desc=trim($_POST['description']??'');$available=isset($_POST['available'])?1:0;if($name===''||!in_array($type,['Sedan','SUV','Luxury','Van'],true)||$seats<1||$seats>20||$price<=0||!filter_var($image,FILTER_VALIDATE_URL)||$desc==='')flash('Please complete all vehicle fields correctly.','danger');elseif($id){$s=$pdo->prepare('UPDATE cars SET name=?,type=?,seats=?,price_per_day=?,image_url=?,description=?,available=? WHERE id=?');$s->execute([$name,$type,$seats,$price,$image,$desc,$available,$id]);flash('Vehicle updated.');}else{$s=$pdo->prepare('INSERT INTO cars(name,type,seats,price_per_day,image_url,description,available) VALUES(?,?,?,?,?,?,?)');$s->execute([$name,$type,$seats,$price,$image,$desc,$available]);flash('Vehicle added.');}redirect('admin.php?section=vehicles');}
if($action==='delete_car'){$id=(int)$_POST['id'];$s=$pdo->prepare("SELECT COUNT(*) FROM bookings WHERE car_id=? AND status IN ('Pending','Confirmed')");$s->execute([$id]);if((int)$s->fetchColumn()>0)flash('Cannot delete a vehicle with active bookings.','danger');else{$s=$pdo->prepare('DELETE FROM cars WHERE id=?');$s->execute([$id]);flash('Vehicle deleted.');}redirect('admin.php?section=vehicles');}
if($action==='booking_status'){$id=(int)$_POST['id'];$status=$_POST['status']??'';if(in_array($status,['Pending','Confirmed','Completed','Cancelled'],true)){$s=$pdo->prepare('UPDATE bookings SET status=? WHERE id=?');$s->execute([$status,$id]);flash('Booking status updated.');}redirect('admin.php?section=bookings');}}
$section=$_GET['section']??'overview';$cars=$pdo->query('SELECT * FROM cars ORDER BY id DESC')->fetchAll();$bookings=$pdo->query('SELECT b.*,u.name AS customer_name,u.email,c.name AS car_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN cars c ON c.id=b.car_id ORDER BY b.created_at DESC')->fetchAll();$customers=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();$revenue=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM bookings WHERE status IN ('Confirmed','Completed')")->fetchColumn();$pending=count(array_filter($bookings,fn($b)=>$b['status']==='Pending'));$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM cars WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$pageTitle='Admin Dashboard';require __DIR__.'/partials/header.php';
?>
