<?php if($section==='overview'):?><div class="welcome-banner mb-4"><div class="d-flex justify-content-between align-items-center"><div><h3 class="fw-bold">Welcome Back, Admin!</h3><p class="mb-0">Manage your car rental business easily and efficiently.</p></div><div class="display-5">🚘</div></div></div><div class="row g-3 mb-4"><?php foreach([['Total Vehicles',count($cars),'🚘'],['Total Customers',$customers,'👥'],['Total Bookings',count($bookings),'📋'],['Pending Requests',$pending,'🕒']] as [$label,$num,$icon]):?><div class="col-sm-6 col-xl-3"><div class="card metric-card"><div class="card-body d-flex justify-content-between"><div><div class="text-secondary small"><?=$label?></div><div class="metric-number"><?=$num?></div></div><div class="metric-icon"><?=$icon?></div></div></div></div><?php endforeach;?></div><div class="row g-3 mb-4"><div class="col-lg-7"><div class="card dash-card h-100"><div class="card-body"><h5 class="fw-bold">Rental Overview</h5><p class="small text-secondary">Confirmed and completed rental revenue</p><div class="display-6 fw-bold text-primary"><?=money($revenue)?></div><div class="chart-bars"><span style="height:32%"></span><span style="height:46%"></span><span style="height:39%"></span><span style="height:61%"></span><span style="height:55%"></span><span style="height:78%"></span><span style="height:68%"></span><span style="height:92%"></span></div><div class="d-flex justify-content-between small text-secondary mt-2"><span>Activity illustration</span><span>All time</span></div></div></div></div><div class="col-lg-5"><div class="card dash-card h-100"><div class="card-body"><h5 class="fw-bold">Quick Actions</h5><div class="d-grid gap-2 mt-3"><a class="btn btn-primary" href="admin.php?section=vehicles&new=1">＋ Add New Vehicle</a><a class="btn btn-success" href="admin.php?section=bookings">Manage Bookings</a><a class="btn btn-outline-primary" href="index.php#fleet">View Public Website</a></div><hr><div><span class="activity-dot"></span>Fleet and booking data is live from MySQL.</div></div></div></div></div><div class="card dash-card"><div class="card-body"><h5 class="fw-bold">Recent Bookings</h5><?php $rows=array_slice($bookings,0,6);if(!$rows):?><p class="text-secondary mb-0">No bookings yet.</p><?php else:?><div class="table-responsive"><table class="table dash-table"><thead><tr><th>Customer</th><th>Vehicle</th><th>Dates</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td><?=h($b['customer_name'])?></td><td><?=h($b['car_name'])?></td><td><?=h($b['start_date'])?> – <?=h($b['end_date'])?></td><td><?=money($b['total'])?></td><td><?=h($b['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div>
<?php elseif($section==='vehicles'):?><div class="d-flex justify-content-between align-items-center mb-3"><div><h3 class="fw-bold">Vehicle Management</h3><p class="text-secondary mb-0">Add, edit and manage your fleet.</p></div><a class="btn btn-primary" href="admin.php?section=vehicles&new=1">＋ Add Vehicle</a></div><?php if(isset($_GET['new'])||$edit):?><div class="card dash-card mb-4"><div class="card-body"><h5><?=$edit?'Edit Vehicle':'Add Vehicle'?></h5><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_car"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="col-md-6"><label class="form-label text-dark">Name</label><input class="form-control" name="name" required value="<?=h($edit['name']??'')?>"></div><div class="col-md-3"><label class="form-label text-dark">Type</label><select class="form-select" name="type"><?php foreach(['Sedan','SUV','Luxury','Van'] as $t):?><option <?=($edit['type']??'Sedan')===$t?'selected':''?>><?=$t?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label text-dark">Seats</label><input class="form-control" type="number" name="seats" min="1" max="20" value="<?=(int)($edit['seats']??5)?>"></div><div class="col-md-4"><label class="form-label text-dark">Price per day (USD)</label><input class="form-control" type="number" name="price" min="1" step=".01" value="<?=h((string)($edit['price_per_day']??''))?>" required></div><div class="col-md-8"><label class="form-label text-dark">Image URL</label><input class="form-control" type="url" name="image_url" value="<?=h($edit['image_url']??'')?>" required></div><div class="col-12"><label class="form-label text-dark">Description</label><textarea class="form-control" name="description" required><?=h($edit['description']??'')?></textarea></div><div class="col-12 form-check ms-2"><input class="form-check-input" type="checkbox" name="available" id="available" <?=!isset($edit)||$edit['available']?'checked':''?>><label class="form-check-label text-dark" for="available">Available</label></div><div class="col-12"><button class="btn btn-primary">Save Vehicle</button> <a href="admin.php?section=vehicles" class="btn btn-light">Cancel</a></div></form></div></div><?php endif;?><div class="card dash-card"><div class="table-responsive"><table class="table dash-table"><thead><tr><th>Vehicle</th><th>Type</th><th>Price/day</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($cars as $c):?><tr><td><?=h($c['name'])?></td><td><?=h($c['type'])?></td><td><?=money($c['price_per_day'])?></td><td><?=$c['available']?'Available':'Unavailable'?></td><td><a class="btn btn-sm btn-outline-primary" href="admin.php?section=vehicles&edit=<?=(int)$c['id']?>">Edit</a> <form method="post" class="d-inline" onsubmit="return confirm('Delete this vehicle?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete_car"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
<?php elseif($section==='bookings'):?><h3 class="fw-bold">All Bookings</h3><p class="text-secondary">Review customer reservations and update their status.</p><div class="card dash-card"><div class="table-responsive"><table class="table dash-table"><thead><tr><th>Customer</th><th>Vehicle</th><th>Dates</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($bookings as $b):?><tr><td><?=h($b['customer_name'])?><div class="small text-secondary"><?=h($b['email'])?></div></td><td><?=h($b['car_name'])?></td><td><?=h($b['start_date'])?> – <?=h($b['end_date'])?></td><td><?=money($b['total'])?></td><td><?=h($b['payment_method'])?></td><td><?=h($b['status'])?></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="booking_status"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><select class="form-select form-select-sm" name="status"><?php foreach(['Pending','Confirmed','Completed','Cancelled'] as $st):?><option <?=$b['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
